export type KeyringShape = "rectangle" | "square" | "circle" | "triangle" | "ellipse" | "heart" | "star" | "hexagon" | "cube";
export type KeyringTextSize = "small" | "medium" | "large";
export type KeyringTextOrientation = "horizontal" | "vertical";
export type KeyringRelief = "flat" | "raised" | "recessed";
export type KeyringFont = "helvetica" | "rounded" | "condensed" | "inter" | "mono";
export type KeyringFace = "front" | "back";
export type KeyringPosition = { x: number; y: number };
export type KeyringLettering = KeyringPosition & { size: KeyringTextSize; orientation: KeyringTextOrientation; relief?: KeyringRelief; font?: KeyringFont };
export type KeyringDesignDetails = { hole?: string; front?: KeyringLettering; back?: KeyringLettering & { text: string } };
export type KeyringHoleOption = KeyringPosition & { id: string; label: string };
export const keyringShapeNames: Readonly<Record<KeyringShape, string>>;
export const keyringShapes: readonly KeyringShape[];
export const keyringTextSizes: readonly KeyringTextSize[];
export const keyringTextOrientations: readonly KeyringTextOrientation[];
export const keyringTextSizeNames: Readonly<Record<KeyringTextSize, string>>;
export const keyringTextOrientationNames: Readonly<Record<KeyringTextOrientation, string>>;
export const keyringReliefs: readonly KeyringRelief[];
export const keyringReliefNames: Readonly<Record<KeyringRelief, string>>;
export const keyringFonts: readonly KeyringFont[];
export const keyringFontNames: Readonly<Record<KeyringFont, string>>;
export const keyringRaisedFontName: string;
export const defaultKeyringLettering: Readonly<Required<KeyringLettering>>;
export function keyringSizesForRelief(relief?: KeyringRelief): readonly KeyringTextSize[];
export const keyringStarPoints: readonly KeyringPosition[];
export const keyringHexagonPoints: readonly KeyringPosition[];
export const keyringHoleIds: readonly string[];
export function keyringHoleOptions(shape: KeyringShape): readonly KeyringHoleOption[];
export function keyringHoleName(shape: KeyringShape, id: string): string | undefined;
export const keyringMaxTextLength: number;
export function keyringTextLimit(shape: KeyringShape, orientation: KeyringTextOrientation, size: KeyringTextSize, relief?: KeyringRelief): number;
export const keyringLetteringPattern: RegExp;
export function cleanKeyringLettering(text: string): string;
export function keyringDesignLabels(shape: KeyringShape, inscription: string | undefined, details: KeyringDesignDetails): string[];
